quests[24775] = { id = 24775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24776] = { id = 24776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Ortezza im Osten.", sourceObjective = "Trefft Ortezza auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nIhr seht aber ziemlich wild aus. Grimmige Augen. Vielleicht wird aus Euch noch ein echter {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24777] = { id = 24777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Dinge schlagen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr auch versteht, wie Ihr die Waffe zu schwingen habt, mit der Ihr da rumfuchtelt.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Angriffen... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24778] = { id = 24778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Jägers", description = "Wenn Ihr den Bogen raushabt, findet Ihr heraus, wie man neue Tricks macht.\n\nZuerst müsst Ihr lernen, zwischen Schüssen eine ruhige Hand zu behalten, sonst seid Ihr schnell erschöpft und richtet keinen wirklichen Schaden mehr an.\n\nLos, sammelt noch mehr Erfahrungen, bis Ihr es rausgefunden habt, und kommt dann wieder. Lasst es mich wissen, wenn Ihr meint, dass Ihr es drauf habt.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Zuverlässiger Schuss zu erlernen. Wendet den zuverlässigen Schuss 5-mal bei einem Tikiziel an.", sourceObjectiveStatus = "unverified-source-field" }
quests[24779] = { id = 24779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[24780] = { id = 24780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24781] = { id = 24781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24782] = { id = 24782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Tunari im Osten.", sourceObjective = "Trefft Tunari auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nDafür seht Ihr aber sehr ausgeglichen aus. Ruhige Augen. Vielleicht wird aus Euch noch ein echter {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24783] = { id = 24783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Ziele treffen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr die Grundlagen der heiligen Künste versteht.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Zaubern... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24784] = { id = 24784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das richtige Wort", description = "Wenn Ihr da draußen in der Welt mehr Fähigkeiten bekommt, werdet Ihr neue Kräfte entdecken.\n\nProbiert es aus und versucht, stärker zu werden. Kommt dann wieder, wenn Ihr etwas Neues gelernt habt. Ihr könnt mir dann zeigen, was Ihr drauf habt.", sourceObjective = "Ihr müsst Stufe 3 erreichen, um Schattenwort: Schmerz zu erlernen. Wendet es 5-mal bei Tiki-Trainingsattrappen an.", sourceObjectiveStatus = "unverified-source-field" }
quests[24785] = { id = 24785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[24786] = { id = 24786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24787] = { id = 24787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", sourceObjectiveStatus = "unverified-source-field" }
