quests[24823] = { id = 24823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Zerstörung", progress = "Ihr wollt also tatsächlich weiter dem Weg der Zerstörung folgen, {name}?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
quests[24824] = { id = 24824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gestörte Erde", description = "Wir sind hier, um die Narben der Lande zu überwachen und nach weiteren Zeichen der Instabilität Ausschau zu halten. Bisher haben wir noch keine gesehen, aber ein kataklysmisches Nachbeben könnte das Brachland noch weiter verheeren.\n\nIm Nordosten, in der Nähe des Abgrunds, wüten völlig außer Kontrolle geratene Erdelementare. Um die Erde zu besänftigen, müssen diese hin und wieder vernichtet werden und ihre Essenz in einem Ritual zurückgegeben werden. Wenn Ihr uns helft, das zu tun, {class}, werde ich Euch mit Freuden belohnen.", sourceObjective = "Besorgt 4 unruhige Erdfragmente von gestörten Erdelementaren.", progress = "Die Elemente müssen sorgfältig in der Balance gehalten werden. Die Rückführung der Essenzen ist ein Schlüssel dafür. Ich hoffe, Ihr habt sie eingesammelt...", completion = "Ich danke Euch, mein Freund. Es ist wichtig, dass wir die Erde auf jede erdenkliche Weise besänftigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24825] = { id = 24825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Weisheit", sourceObjective = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel.", sourceObjectiveStatus = "unverified-source-field" }
quests[24826] = { id = 24826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Vergeltung", progress = "Ihr wollt also tatsächlich weiter dem Weg der Vergeltung folgen, {name}?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
quests[24827] = { id = 24827, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Mutes", progress = "Ihr wollt also tatsächlich weiter dem Weg des Mutes folgen, {name}?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
