quests[24829] = { id = 24829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Zerstörung", progress = "Ihr wollt also tatsächlich weiter dem Weg der Zerstörung folgen, {name}?", completion = "Ihr seid ein wahrer Champion unserer Sache, {name}. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nDer Feind spricht Euren Namen nur flüsternd aus, denn er weiß, dass Ihr eine Macht seid, mit der er rechnen muss.\n\nNehmt dieses bescheidene Geschenk als Dank für Eure vielen Triumphe an." }
quests[24830] = { id = 24830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Weisheit", progress = "Ihr wollt also tatsächlich weiter dem Weg der Weisheit folgen, {name}?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
