quests[24832] = { id = 24832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Vergeltung", progress = "Ihr wollt also tatsächlich weiter dem Weg der Vergeltung folgen, {name}?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
quests[24833] = { id = 24833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Vergeltung", progress = "Ihr wollt also tatsächlich weiter dem Weg der Vergeltung folgen, {name}?", completion = "Ihr seid ein wahrer Champion unserer Sache, {name}. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nEs wird gemunkelt, dass die Lakaien der Geißel Euch mehr fürchten als den Lichkönig selber.\n\nNehmt dieses bescheidene Geschenk als Dank für Eure vielen Triumphe an." }
quests[24834] = { id = 24834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Mutes", progress = "Ihr wollt also tatsächlich weiter dem Weg des Mutes folgen, {name}?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
quests[24835] = { id = 24835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Mutes", progress = "Ihr wollt also tatsächlich weiter dem Weg des Mutes folgen, {name}?", completion = "Ihr seid ein wahrer Champion unserer Sache, {name}. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nIhr seid eine Quelle der Inspiration für unsere Verbündeten und Euer unerschütterlicher Mut lässt selbst die erfahrensten Generäle des Feindes innehalten.\n\nNehmt dieses bescheidene Geschenk als Dank für Eure vielen Triumphe an." }
