quests[24848] = { id = 24848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerwerk bei der Güldenen Rose", description = "Kind, hier geht es um mehr als bloß Parfüm. In dieser Kiste waren ein paar Raketen und sie sind mit irgendeiner chemischen Ladung gefüllt. Hier kann ich sie nicht analysieren, aber ich werde Euch den Weg ins Labor ersparen.\n\nIhr müsst nur den Typ aufspüren, der sie hergestellt hat. Ich kenne das Brandzeichen. Flenni Rostrakete.\n\nIch habe einen Tipp von einer vertrauenswürdigen Quelle erhalten, dass er sich hier in Sturmwind aufhält und es sich in der Güldenen Rose gut gehen lässt. Er soll sogar eine Dame bei sich haben, mit Namen Marion Sutton. Macht Euch auf zur Güldenen Rose und findet heraus, was sie weiß.", sourceObjective = "Redet mit Marion Sutton in der Güldenen Rose im Handelsdistrikt von Sturmwind.", completion = "Ihr... Ihr seid nicht Flenni. Hat er Euch geschickt? Er ist so spät dran, ich hatte schon die Hoffnung aufgegeben...\n\n<Tränen schimmern in ihren Augen, als sie begreift, dass Ihr nicht dort seid, um eine Nachricht von Flenni zu überbringen.>\n\nDas passt gar nicht zu meinem Flenni, aber was für eine andere Möglichkeit gibt es?", sourceObjectiveStatus = "unverified-source-field" }
quests[24849] = { id = 24849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Fersen", description = "Ich fange am besten von vorne an. Es war Liebe auf den ersten Blick, {name}. Da war einfach etwas Besonderes an diesem Goblin, schon als meine Augen ihn das erste Mal erblickten.\n\nNachdem wir eine wundervolle Woche miteinander verbracht hatten, meinte Flenni, dass er an eine Menge Geld gekommen sei und mich auf eine Reise in die Südlichen Meere mitnehmen wolle! Könnt Ihr Euch das vorstellen?\n\nWie auch immer, er meinte, ich solle meine Sachen packen, während er noch zur Bank, zum Auktionshaus und zum Barbier müsse. Aber er ist nie wieder aufgetaucht! Ich fange langsam an zu glauben, dass er einfach nur ein großer Lügner ist!", sourceObjective = "Sucht Flenni Rostrakete im Zählhaus von Sturmwind, im Auktionshaus und beim Barbier von Sturmwind.", completion = "Er hat also nur davon gesprochen, dass er die Stadt mit all seinem Geld verlassen will? Dann hat er mich wirklich sitzen lassen, oder?\n\nOh, was war ich bescheuert, mich in ihn zu verlieben, aber wie hätte ich es verhindern können? Er war so unwiderstehlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[24850] = { id = 24850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flennis Flamme", description = "<Junge/Mädel>, hier geht es um mehr als bloß Parfüm. In dieser Kiste waren ein paar Raketen und sie sind mit irgendeiner chemischen Ladung gefüllt. Hier kann ich sie nicht analysieren, aber ich werde Euch den Weg ins Labor ersparen.\n\nIhr müsst nur den Typ aufspüren, der sie hergestellt hat. Ich kenne das Zeichen des Herstellers. Flenni Rostrakete.\n\nIch habe gehört, dass er es sich hier in Orgrimmar gut gehen lässt. Und es kommt noch besser, er soll sogar eine Freundin haben... eine Orc-Dame mit Namen Roka. Sie will sich mit ihm bei Gotris Reiseausstattung in der Gasse treffen, bevor sie ihre Flucht antreten.", sourceObjective = "Redet mit Roka bei Gotris Reiseausstattung in der Gasse in Orgrimmar.", completion = "Ihr seid nicht Flenni. Er hätte schon vor einer Stunde hier sein sollen! Was habt Ihr mit ihm angestellt?\n\n<Roka scheint sich zu beruhigen, als Ihr ihr erklärt, dass Ihr selber nach Flenni sucht. Dann schimmern Tränen in ihren Augen.>\n\nDas sieht meinem süßen Flenni gar nicht ähnlich. Meint Ihr, ihm ist etwas zugestoßen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24851] = { id = 24851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Fersen", description = "Ich fange am besten von vorne an. Es war Liebe auf den ersten Blick, {name}. Da war einfach etwas Besonderes an diesem Goblin, schon als meine Augen ihn das erste Mal erblickten.\n\nNachdem wir eine wundervolle Woche miteinander verbracht hatten, meinte Flenni, dass er an eine Menge Geld gekommen sei und mich auf eine Reise in die Südlichen Meere mitnehmen wolle! Könnt Ihr Euch das vorstellen?\n\nWie auch immer, er meinte, ich solle meine Sachen packen, während er noch zur Bank, zum Auktionshaus und zum Barbier müsse. Aber er ist nie wieder aufgetaucht! Ich fange langsam an zu glauben, dass er einfach nur ein großer Lügner ist!", sourceObjective = "Sucht Flenni Rostrakete in der Bank von Orgrimmar im Tal der Stärke, dem Auktionshaus und dem Barbier von Orgrimmar.", completion = "Er hat also nur davon gesprochen, dass er die Stadt mit all seinem Geld verlassen will? Dann hat er mich wirklich sitzen lassen, oder?\n\nIch kann nicht glauben, dass ich auf einen so schrecklichen Goblin reingefallen bin! Aber er war so unwiderstehlich, als wir uns das erste Mal sahen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24852] = { id = 24852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Stamm in Gefangenschaft", description = "Trotz ihrer geringen Größe sind die Borstennacken uns zahlenmäßig überlegen. Ein Angriff des Rudels kann selbst den größten Tauren überwältigen. Viele unserer Initianden haben zu den Waffen gegriffen, um ihre Heimat zu verteidigen - einige haben ihr Leben dafür gegeben und ein paar befinden sich in Gefangenschaft.\n\nIch bitte Euch, findet ihre Käfige und befreit sie. Die Schlacht sollte die Stacheleber ablenken.", sourceObjective = "Öffnet 4 Stacheleberkäfige.", progress = "Es sind nicht genug der Unseren zurückgekehrt, {name}. Geht und befreit mehr {race}. Seid mutig!", completion = "Dank Euch sind unsere Krieger wieder frei und können ihre Heimat verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24854] = { id = 24854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Sturmklaue", description = "Zen'Aliri lernt die Kunst der Druiden, {race}. Eines Tages ist Zen'Aliri hoffentlich auch ein Druide der Kralle und kann als Sturmkrähe über diesen Krater schweben.\n\nAber sein Meister sagt, dass Zen'Aliri vorerst noch hier warten muss. Also wartet Zen'Aliri.\n\nEr kennt einen anderen Druiden, der vielleicht Eure Hilfe brauchen könnte. Sein Name ist Garl Sturmklaue. Er hält sich irgendwo im Osten auf und untersucht Reagenzien. Vielleicht könntet Ihr mit ihm reden?", sourceObjective = "Meldet Euch bei Garl Sturmklaue am Eingang zum Krater von Un'Goro.", completion = "Es war klug von Zen'Aliri, Euch zu mir zu schicken. Ich bin mit meinen Studien in einer Sackgasse angelangt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24855] = { id = 24855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anormale Flora", description = "Schaut nur, wie merkwürdig die Pflanzenwelt auf die Blutblüten in den Aufwühlenden Gärten im Norden reagiert. Es ranken sich noch mehr Blumen und Schlingpflanzen um die Bäume als sonst. Große, sporenreiche Blüten erheben sich dort, wo sonst keine waren.\n\nDas Land spricht zu uns, {race}. Die Blutblüten zerstören das Gleichgewicht.\n\nAls letzte Aufgabe möchte ich Euch bitten, die ausgewachsenen umherwandernden Blutblüten aufzusuchen und ihre Zahl zurechtzustutzen.", sourceObjective = "Tötet 11 Blutblüten. Eine beliebige Kombination aus ausgewachsenen Blutblüten ist zulässig.", completion = "Euch umgibt der Geruch der Blutblütenpollen, {class}. Das ist gut.\n\nIhr habt Euch Eure Belohnung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[24856] = { id = 24856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drohende Invasion!", description = "Eure Arbeit hier ist vorerst getan, aber das heißt noch lange nicht, dass Ihr jetzt die Hände in den Schoß legen könnt.\n\nErinnert Ihr Euch noch an Megs Schredderschreck, unsere ehemalige Marketingbeauftragte? Sie hat jetzt ein paar andere Aufgaben jenseits der Hügel im Südosten übernommen, direkt hinter dem Raptorenbuckel. Wenn Ihr dem Weg nach Osten aus der Stadt heraus und an der Gabelung nach Süden folgt, könnt Ihr sie nicht verpassen.\n\nAnscheinend gibt es dort ein paar Probleme mit den Schlangenwesen in den Ruinen an der Küste. Schaut doch einmal nach, ob Ihr etwas dagegen unternehmen könnt, ja?", sourceObjective = "Sprecht mit Megs Schredderschreck am westlichen Eingang zu den Ruinen von Vashj'elan auf den Verlorenen Inseln.", completion = "Boss, wir haben ein Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[24857] = { id = 24857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Camp Narache", description = "Nachdem Ihr die Karte sorgfältig studiert habt, erkennt Ihr, dass Ihr die Pläne für eine ausgeweitete Belagerung von Camp Narache entdeckt habt, die von dem Kriegshäuptling der Borstennacken entworfen wurden.\n\nHäuptling Falkenwind kann mit dieser Information sicher einiges anfangen!", sourceObjective = "Bringt die Angriffspläne der Borstennacken zu Häuptling Falkenwind in Camp Narache.", sourceObjectiveStatus = "unverified-source-field" }
quests[24858] = { id = 24858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertreter des Bilgewasserkartells", description = "Sieht aus, als bereiten sich die Naga in den Ruinen da unten auf einen Angriff auf Instastadt vor. Zumindest habe ich hier viele tote Späher als Beweis.\n\nIch weiß nicht, wie es Euch geht, aber ich will es nicht darauf ankommen lassen. Wir müssen ihnen zuvorkommen!\n\nKönntet Ihr den Grundstein für unsere neuen Besitztümer an der Küste legen, indem Ihr ihre Banner durch unsere eigenen ersetzt? Das ist erstklassiges Bauland dort unten!", sourceObjective = "Zerstört 10 Nagabanner und ersetzt sie durch Banner des Bilgewasserkartells.", completion = "Ich wünschte, ich hätte den Ausdruck auf ihren schuppigen Gesichtern sehen können, als Ihr ihre Banner in die Luft gejagt und durch unsere ersetzt habt!\n\nObwohl, wenn ich es mir genau überlege, möchte ich ihnen nicht nah genug sein, um ihre Schlangenzungen zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24859] = { id = 24859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagahaut", description = "Hinter vorgehaltener Hand spricht man von einem Material, das so fein ist, sich so zart anfühlt, dass Goblins mit einem exquisiten Geschmack einen Haufen Knete dafür ausgeben.\n\nIch spreche natürlich von Nagahaut!\n\n<Brett schaut sich um, um sicherzugehen, dass ihn keiner belauscht.>\n\nIch weiß, dass Ihr dort hinunter geht und gegen diese Schlangen kämpfen müsst. He, sie brauchen ihre Haut ja sowieso nicht mehr. Sie sind dann ja schließlich tot!", sourceObjective = "Sammelt 5 intakte Nagahäute.", progress = "Nun? Wie viele habt Ihr für mich? Ich finde, wenn wir den Gewinn 95 zu 5 aufteilen, ist das mehr als gerecht.", completion = "Ich sage Euch, wir werden stinkreich! Natürlich vorausgesetzt, wir kommen von dieser Insel runter.", sourceObjectiveStatus = "unverified-source-field" }
quests[24860] = { id = 24860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nützliche Schutzmaßnahmen", description = "Wie Ihr wisst sind die Naga die mutierte und hübschere Version der Kaldorei, besser bekannt als Nachtelfen. Fragt nicht… Es ist eine lange Geschichte.\n\nJedenfalls bin ich mir sicher, dass Ihr das ein oder andere Artefakt 'sicherstellen' könntet, wenn Ihr da unten in den Ruinen seid. Ihr versteht doch, was ich meine?\n\nWir müssen sie in den Häusern reicher Sammler auf der ganzen Welt beschützen. Oder etwa nicht?", sourceObjective = "Sammelt 12 Kaldoreiartefakte.", sourceObjectiveStatus = "unverified-source-field" }
quests[24861] = { id = 24861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riten zum Ende, Riten zum Beginn", description = "Unser Camp ist nun sicher und die Stacheleber sind dank Euch vertrieben. Ihr könnt Euch meines Danks sicher sein für das, was Ihr für meine Mutter, meinen Sohn und mein Volk getan habt.\n\nEs ist an der Zeit, Großmutter Falkenwind Ruhe zu schenken. Legt die letzte Opfergabe zu ihren Füßen, {name}, und wir werden Abschied nehmen.", sourceObjective = "Benutzt die Bestattungsgabe an Großmutter Falkenwinds Bestattungsstelle.", progress = "Seid nicht schüchtern, {name}. Es ist mir eine Ehre, dass Ihr die letzte Gabe legt.", completion = "Es gibt überall Gleichgewicht. Nun, da Großmutter Falkenwind ihre letzte Reise antritt, werdet Ihr Euch auf Eure erste begeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24862] = { id = 24862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spießrutenlauf", description = "Schaut Euch um, {class}. Wir hatten kein Glück dabei, die Horde von den versteckten Pfaden, die einen Ausblick auf dieses Tal gewähren, zu verdrängen. Sie tauchen aus dem Nichts auf, um unsere Nachschubkarawanen zu überfallen und dann verschwinden sie in die Hügel!\n\nIhr müsst Euch der Gefahr aussetzen, zur Ehrenwacht zu laufen und sie darüber zu unterrichten, dass die Straßen immer noch nicht sicher sind. Sprecht mit Mattingly, dem Nachschuboffizier am Tor.\n\nUnd tötet unterwegs ein paar von diesen Ungeheuern!", sourceObjective = "Tötet 8 Späher des Jägerhügels.", completion = "Sie überfallen auch die Straßen ins Steinkrallengebirge? Hier bekommt man aber auch keine Ruhe. Wo kommen die überhaupt her?", sourceObjectiveStatus = "unverified-source-field" }
quests[24863] = { id = 24863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Belagerung durchbrechen", description = "Hordespäher, die sich in den Ruinen vor uns verbergen, haben meinen Nachschubzug aus dem Hinterhalt überfallen. Nur zwei meiner Leibwachen haben das überlebt. Und ich? Ich hatte mal Haare!\n\nDie Vorräte, die ich abliefern sollte, liegen verstreut in den Ruinen vor uns. Sammelt sie ein und bringt sie zu Janice Mattingly in der Ehrenwacht. Wenn wir sie schon nicht ins Steinkrallengebirge bringen können, dann sorgen wir wenigstens dafür, dass sie nicht der Horde in die Hände fallen...", sourceObjective = "Sammelt 10 für das Steinkrallengebirge bestimmte Vorratskisten in den Ruinen westlich der Ehrenwacht auf.", progress = "Wie sieht es da draußen aus, {name}?", completion = "Was... unsere Vorräte? Die waren fürs Steinkrallengebirge bestimmt.\n\nEgal, so, wie das hier läuft, brauchen wir sie ohnehin dringender hier. Die Ehrenwacht ist von der Küste abgeschnitten worden, {name}. Kommandant Singleton ist mit seinem Latein am Ende.", sourceObjectiveStatus = "unverified-source-field" }
quests[24864] = { id = 24864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwiderstehliches Poolpony", description = "Ich habe einen Plan und Ihr seid <der Einzige, der/die Einzige> die; verrückt genug ist, ihn in die Tat umzusetzen!\n\nIch möchte, dass Ihr das Poolpony zum Laichbecken von Vashj'elan bringt und aufblast. Schwimmt dann auf dem Pony zu ihren Jungen. Ich wette, Ihr könnt die Jungen dazu bringen, Euch zu folgen.\n\nBringt sie hierher. Dann machen wir mit der nächsten Phase unseres Plans weiter.", sourceObjective = "Benutzt das unwiderstehliche Poolpony, um 12 Nagajunge anzulocken.", progress = "Das sind nicht genug Junge.", completion = "Oh, die sind so süß! Ich wünschte, wir könnten sie in kleine Plüschtiere verwandeln und für eine Gazillion Moneten verkaufen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24865] = { id = 24865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist das noch gut?", description = "Ihr findet etwas, das wie eine Nahrungsmittelkiste aussieht, die beim Verlassen dieses Lagers vergessen wurde. Auf der Seite der Kiste erkennt Ihr einen Stempel mit den Worten \"EIGENTUM VON MARSCHALLS EXPEDITION\".\n\nVielleicht findet Ihr ja jemanden, der das hier brauchen könnte.", sourceObjective = "Bringt die Kiste mit Lebensmitteln zu Williden Marschall in Marschalls Wehr zurück.", progress = "Was habt Ihr da?", completion = "Oh… Das ist aber ganz schön altes Essen. He, Hol'anyee, schau dir das an! Dieser {race} hat uns unsere zurückgelassenen Rationen gebracht!\n\nNein, nicht von Marschalls Zuflucht… aus dem alten Basislager!\n\n\n\nIch bin mir nicht sicher, ob ich da hineinschauen möchte. Ich schätze, ich werde einfach Nolen die Kiste geben. Er weiß sicher, was damit zu tun ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24866] = { id = 24866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verlassenes Forschungslager", description = "Ihr findet etwas, das wie ein Stück einer Forscherausrüstung aussieht, das beim Verlassen dieses Lagers vergessen wurde. Auf der Seite des Geräts sind die Worte \"EIGENTUM VON MARSCHALLS EXPEDIZION\" eingeritzt.\n\nVielleicht findet Ihr ja jemanden, der das hier brauchen könnte.", sourceObjective = "Bringt die Forscherausrüstung zu Hol'anyee Marschall in Marschalls Wehr zurück.", progress = "Ja, {name}?", completion = "Da brat mir einer… Das ist Sappalots altes tragbares Dinomometer! Wo habt Ihr das gefunden?\n\nIch bin überrascht, dass es nach all den Jahren überhaupt noch funktioniert. Ich werde es sofort zu Sappalot bringen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24868] = { id = 24868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt auf, oder…!", description = "{name}, Ihr und Ass müsst diese Nagajungen dort hinunter führen und sie als Druckmittel benutzen, um ihren Anführer zur Kapitulation zu zwingen!\n\nAss weiß, wo er auf der Südseite der Ruinen entlanggehen muss. Folgt ihm einfach.", sourceObjective = "Vernichtet den Anführer der Naga in den Ruinen von Vashj'elan.", completion = "Ein Gesichtsloser aus den Tiefen? Was soll das sein? Das klingt NICHT nach einem Naga!\n\nNun, Ihr habt es getötet, was immer es auch war. Wir haben andere Fische zu fangen…", sourceObjectiveStatus = "unverified-source-field" }
quests[24869] = { id = 24869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entprogrammieren", description = "Wir hatten gehofft, einen Mann in den Reihen des Kults der Verdammten platzieren zu können, um einen besseren Eindruck von den Machenschaften des Lichkönigs zu bekommen, aber wir... haben die Überredungskünste von Arthas und seiner dunklen Gesandten, Lady Todeswisper, unterschätzt.\n\nUnser Mann, Darnavan, ist jetzt einer von ihnen.\n\nWenn Ihr vorhabt, Euch einen Weg durch das Oratorium vor uns zu bahnen, so haltet Eure Augen bitte nach Darnavan auf. Wenn Ihr ihn uns lebend übergeben könntet, könnten wir versuchen, die Hirnwäsche des Kults rückgängig zu machen.", sourceObjective = "Bezwingt Lady Todeswisper, aber stellt dabei sicher, dass Darnavan überlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24870] = { id = 24870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Bollwerks", description = "Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Allianzhunde auf der anderen Seite!\n\nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.\n\nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.", sourceObjective = "Erledigt den verrottenden Frostriesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24871] = { id = 24871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Bollwerks", description = "Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Hunde von der Horde auf der anderen Seite!\n\nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.\n\nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.", sourceObjective = "Erledigt den verrottenden Frostriesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24872] = { id = 24872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frieden für eine geschundene Seele", description = "Nehmt diesen Kristall des Lebens, und auch Eure Gefährten sollten einen nehmen. Er enthält mächtige Energien aus dem tiefgrünen Drachenschrein in der Drachenöde, und es war mein eigenes Geheimnis, um den dunklen Magien dieses Ortes so lange widerstehen zu können.\n\nWenn Ihr Sindragosa gegenübertretet, bekämpft sie, bis sie geschwächt ist, und dann sollten Eure Gefährten diese Kristalle benutzen, um die Essenz herauszulocken, die in ihr schläft. Wenn Ihr sie dann besiegt, solltet Ihr in der Lage sein, die Essenz aufzunehmen und zum Wyrmruhtempel in der Drachenöde zurückzubringen.", sourceObjective = "Benutzt die Lebenskristall, um Sindragosas Essenz zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24873] = { id = 24873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandelnder Wirt", description = "Professor Seuchenmord ist in sein fauliges Labor eingeschlossen worden, wo er immer tödlichere Kulturen der Seuche gegen uns entwickelt. Wenn wir nur einige reine Proben dieser Gifte in die Finger bekommen könnten, dann könnten unsere Forscher ein Antidot enwickeln und unzählige Leben retten.\n\nEs gibt nur einen Haken... eine nützliche Probe müsste aus zwei aktiven Stämmen bestehen, die sich in einem lebenden Wirt verbinden. Sollte Euch das... Missgeschick... widerfahren, solch ein Wirt zu werden, dann kommt bitte sofort hier her, sodass wir Euch für unsere Studien abernten können.", sourceObjective = "Kehrt zu Alchemistin Adrianna zurück, während Ihr mit der orangenen und der grünen Seuche infiziert seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[24874] = { id = 24874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhöhter Blutdruck", description = "Diese Geißel-Blutsauger - San'layn nennen sie sich - sind mir nicht geheuer. Wir haben einen unserer besten Männer eingesetzt, um ein Auge auf sie zu halten. Aber diesen Morgen ist er unvorsichtig geworden und hat sich erwischen lassen. Er wird gerade von der Königin persönlich verhört, und seine Schreie gellen durch die Blutroten Hallen. Bitte, rettet ihn, bevor es zu spät ist.", sourceObjective = "Rettet den Spitzel Minchar, bevor er hingerichtet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[24875] = { id = 24875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entprogrammieren", description = "Wir hatten gehofft, einen Mann in den Reihen des Kults der Verdammten platzieren zu können, um einen besseren Eindruck von den Machenschaften des Lichkönigs zu bekommen, aber wir... haben die Überredungskünste von Arthas und seiner dunklen Gesandten, Lady Todeswisper, unterschätzt.\n\nUnser Mann, Darnavan, ist jetzt einer von ihnen.\n\nWenn Ihr vorhabt, Euch einen Weg durch das Oratorium vor uns zu bahnen, so haltet Eure Augen bitte nach Darnavan auf. Wenn Ihr ihn uns lebend übergeben könntet, könnten wir versuchen, die Hirnwäsche des Kults rückgängig zu machen.", sourceObjective = "Bezwingt Lady Todeswisper, aber stellt dabei sicher, dass Darnavan überlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24876] = { id = 24876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Bollwerks", description = "Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Hunde von der Horde auf der anderen Seite!\n\nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.\n\nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.", sourceObjective = "Erledigt den verrottenden Frostriesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24877] = { id = 24877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Bollwerks", description = "Als wenn es hier oben nicht schon genug wie im Irrenhaus zuginge, mit einer Zwei-Fronten-Schlacht, die Geißel auf der einen und diese verfluchten Allianzhunde auf der anderen Seite!\n\nWir sind hier, um einen sicheren Landeplatz für unsere Schiffe zu sichern, aber ein gewaltiger Riese auf der anderen Seite des Bollwerks schleudert ständig Geröll auf alles, was sich nähert, und hält damit unsere kleineren Schiffe auf Abstand.\n\nIch will ehrlich sein... er ist eine Nummer zu groß für uns, aber Ihr und Eure Begleiter seht aus, als wäre das eine Kleinigkeit für Euch.", sourceObjective = "Erledigt den verrottenden Frostriesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24878] = { id = 24878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandelnder Wirt", description = "Professor Seuchenmord ist in sein fauliges Labor eingeschlossen worden, wo er immer tödlichere Kulturen der Seuche gegen uns entwickelt. Wenn wir nur einige reine Proben dieser Gifte in die Finger bekommen könnten, dann könnten unsere Forscher ein Antidot enwickeln und unzählige Leben retten.\n\nSolltet Ihr zufällig über ein lebendiges Exemplar stolpern, so bringt es bitte sofort hierher, damit wir es analysieren können.", sourceObjective = "Kehrt zu Alchemistin Adrianna zurück, während Ihr mit der orangenen und der grünen Seuche infiziert seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[24879] = { id = 24879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhöhter Blutdruck", description = "Diese Geißel-Blutsauger - San'layn nennen sie sich - sind mir nicht geheuer. Wir haben einen unserer besten Männer eingesetzt, um ein Auge auf sie zu halten. Aber diesen Morgen ist er unvorsichtig geworden und hat sich erwischen lassen. Er wird gerade von der Königin persönlich verhört, und seine Schreie gellen durch die Blutroten Hallen. Bitte, rettet ihn, bevor es zu spät ist.", sourceObjective = "Rettet den Spitzel Minchar, bevor er hingerichtet wird.", sourceObjectiveStatus = "unverified-source-field" }
